func (r *SourceResource) Update(ctx context.Context, req resource.UpdateRequest, resp *resource.UpdateResponse) {
	var plan SourceModel
	resp.Diagnostics.Append(req.Plan.Get(ctx, &plan)...)
	var request SourceModel
	resp.Diagnostics.Append(configWithPlannedUnknowns(ctx, req.Config, req.Plan, req.State.Raw, &request)...)
	var state SourceModel
	resp.Diagnostics.Append(req.State.Get(ctx, &state)...)
	if resp.Diagnostics.HasError() {
		return
	}
	// An unset line's default travels only when it changes the stored value (the line was just
	// removed): resending an unchanged default can act on its own, e.g. unpause a group's members.
	if !plan.IngestingPaused.Equal(state.IngestingPaused) {
		request.IngestingPaused = plan.IngestingPaused
	}
	vars := map[string]string{}
	vars["id"] = plan.Id.ValueString()
	out, err := r.client.Update(ctx, sourceBinding, vars, r.updateBody(ctx, request, plan, state))
	if err != nil {
		addAPIError(&resp.Diagnostics, "updating source", err, req.Plan.Raw.Type())
		return
	}
	if out == nil {
		out = map[string]interface{}{}
	}
	r.mergeResponse(ctx, state, out)
	resp.State.Raw = stateFromPlan(req.Plan.Raw, req.State.Raw, out)
}

func (r *SourceResource) Delete(ctx context.Context, req resource.DeleteRequest, resp *resource.DeleteResponse) {
	if refuseProtectedDelete(ctx, req.State, "source", &resp.Diagnostics) {
		return
	}
	var state SourceModel
	resp.Diagnostics.Append(req.State.Get(ctx, &state)...)
	if resp.Diagnostics.HasError() {
		return
	}
	vars := map[string]string{}
	vars["id"] = state.Id.ValueString()
	if err := r.client.Delete(ctx, sourceBinding, vars); err != nil {
		addAPIError(&resp.Diagnostics, "deleting source", err, req.State.Raw.Type())
	}
}

func (r *SourceResource) ModifyPlan(ctx context.Context, req resource.ModifyPlanRequest, resp *resource.ModifyPlanResponse) {
	refuseProtectedDestroy(ctx, req, resp, "source")
}

func (r *SourceResource) ImportState(ctx context.Context, req resource.ImportStateRequest, resp *resource.ImportStateResponse) {
	resource.ImportStatePassthroughID(ctx, path.Root("id"), req, resp)
}

